#!/usr/bin/env python3
"""fit25_hand.py — ручные правки после `fit25.py apply` (запускается один раз после каждой пересборки; повторный запуск ничего не меняет).
Вводит полные названия актов там, где после сокращения осталось только краткое, уточняет ссылку у цитаты и возвращает строку,
на которую опирается блок «Главное для запоминания»."""
import os, subprocess
os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
def rd(q): return open('adp2/q%03d.txt' % q, encoding='utf-8').read()
def wr(q, t): open('adp2/q%03d.txt' % q, 'w', encoding='utf-8').write(t)
def rep(q, a, b):
    t = rd(q)
    if b in t: return
    assert t.count(a) == 1, 'q%03d «%s»: найдено %d' % (q, a[:50], t.count(a))
    wr(q, t.replace(a, b)); print('q%03d ~ %s' % (q, a[:60]))
def ins_after(q, anchor, new):
    """после строки, начинающейся с anchor, вставить строку new (того же перечня)"""
    L = rd(q).split('\n')
    if new in L: return
    k = [i for i, l in enumerate(L) if l.startswith(anchor)]; assert len(k) == 1, 'q%03d «%s»: найдено %d' % (q, anchor[:50], len(k))
    L.insert(k[0] + 1, new); wr(q, '\n'.join(L)); print('q%03d + %s' % (q, new[:60]))
def old(q, pref, rev='30db505'):
    L = subprocess.run(['git', 'show', '%s:.github/answers/adp2/q%03d.txt' % (rev, q)], capture_output=True, text=True).stdout.split('\n')
    k = [l for l in L if l.startswith(pref)]; assert len(k) == 1, 'q%03d старая «%s»: %d' % (q, pref[:40], len(k)); return k[0]

# полное название акта при первом упоминании
rep(69, '(//ч. 1 ст. 2.5 КоАП РФ//;', '(//ч. 1 ст. 2.5 Кодекса Российской Федерации об административных правонарушениях//, далее — КоАП РФ;')
rep(149, '- //Федеральный закон от 07.02.2011 № 3-ФЗ «О полиции»//: //п. 16 ч. 1 ст. 12//',
    '- //Федеральный закон от 07.02.2011 № 3-ФЗ «О полиции»// (далее — Закон о полиции): //п. 16 ч. 1 ст. 12//')
# цитата из КоАП получает свою ссылку
rep(138, 'Норма бланкетная: «в местах, запрещённых федеральным законом». Потребление запрещено',
    'Норма бланкетная: «в местах, запрещённых федеральным законом» (//ч. 1 ст. 20.20 КоАП РФ//). Потребление запрещено')
# блок q137 называет ст. 5.61, 6.1.1, 7.17 — строка о личных неприязненных отношениях возвращается в текст
rep(137, '- **Личные неприязненные отношения:** если конфликт вызван личной ссорой с конкретным человеком (долг, ревность, спор соседей) и направлен только против него — это не хулиганство.',
    old(137, '- **Личные неприязненные отношения:**'))
